{
  "name": "USBTMC 通信组件",
  "name_en": "USBTMC Communication Component",
  "manufacturer": "",
  "description": "一个非物理的软件通信组件，用于通过 USB Test and Measurement Class（USBTMC）协议与实验仪器交换文本命令和响应。它主要负责封装、发送、接收和解析 USBTMC 消息，适合用于基于 USB 的通用测试测量仪器控制。",
  "description_en": "A non-physical software communication component for exchanging text commands and responses with laboratory instruments over the USB Test and Measurement Class (USBTMC) protocol. It mainly handles packaging, sending, receiving, and parsing USBTMC messages for control of generic USB-based test and measurement instruments.",
  "actions": [
    {
      "action_name": "auto-send",
      "description": "通过 USBTMC 向仪器发送文本命令。",
      "description_en": "Send a text command to an instrument over USBTMC."
    },
    {
      "action_name": "auto-recv",
      "description": "通过 USBTMC 接收仪器返回的文本响应。",
      "description_en": "Receive a text response from an instrument over USBTMC."
    },
    {
      "action_name": "auto-build_array",
      "description": "构建 USBTMC Bulk-OUT 消息的字节数组表示。",
      "description_en": "Build the byte-array representation of a USBTMC Bulk-OUT message."
    },
    {
      "action_name": "auto-from_bytes",
      "description": "从原始字节数据解析 USBTMC Bulk-IN 消息。",
      "description_en": "Parse a USBTMC Bulk-IN message from raw byte data."
    }
  ],
  "tag_hints": [
    "USBTMC",
    "USB Test and Measurement Class",
    "SCPI over USB",
    "instrument communication",
    "message packing",
    "response parsing"
  ]
}

